import org.json.JSONArray;
import org.json.JSONObject;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.ArrayList;
import java.text.DecimalFormat;
import org.joget.apps.datalist.service.DataListService;
import org.joget.apps.app.service.AppUtil;

DataListService dataListService = (DataListService) AppUtil.getApplicationContext().getBean("dataListService");

String jsonStr = value;

try {
    jsonStr = jsonStr.trim();
    if (jsonStr.startsWith("**")) {
        jsonStr = jsonStr.substring(2);
    }
    if (jsonStr.endsWith("**")) {
        jsonStr = jsonStr.substring(0, jsonStr.length() - 2);
    }

    JSONArray jsonArray = new JSONArray(jsonStr);

    StringBuilder output = new StringBuilder();

    String uniqueId = "products_" + System.currentTimeMillis();

    output.append("<style>");
    output.append("  .product-summary a { color: #305CDE; text-decoration: none; font-weight: bold; }");
    output.append("  .product-summary a:hover { text-decoration: underline; }");
    output.append("  .custom-table tr:hover { background-color: #305CDE !important; color: white; }");
    output.append("  .nested-table { margin-top: 10px; margin-bottom: 10px; }");
    output.append("  .product-header { background-color: #f8f9fa; font-weight: bold; }");
    output.append("  .raw-material-header { background-color: #e9ecef; font-size: 0.9em; }");
    output.append("  .raw-material-detail { font-size: 0.8em; background-color: #f8f9fa; }");
    output.append("</style>");

    output.append("<script>");
    output.append("  $(document).ready(function() {");
    output.append("    $('#" + uniqueId + "').on('shown.bs.collapse', function() {");
    output.append("      $(this).prev().find('.expand-text').hide();");
    output.append("      $(this).prev().find('.collapse-text').show();");
    output.append("    });");
    output.append("    $('#" + uniqueId + "').on('hidden.bs.collapse', function() {");
    output.append("      $(this).prev().find('.expand-text').show();");
    output.append("      $(this).prev().find('.collapse-text').hide();");
    output.append("    });");
    output.append("  });");
    output.append("</script>");

    output.append("<div class='product-summary'>");
    output.append("  <a data-toggle='collapse' href='#" + uniqueId + "' role='button' aria-expanded='false'>");
    output.append("    <span class='expand-text'><strong>Products & Raw Materials</strong> (" + jsonArray.length() + " products) - Click to expand</span>");
    output.append("    <span class='collapse-text' style='display: none;'><strong>Products & Raw Materials</strong> (" + jsonArray.length() + " products) - Click to collapse</span>");
    output.append("  </a>");
    output.append("</div>");

    output.append("<div class='collapse' id='" + uniqueId + "'>");

    DecimalFormat df = new DecimalFormat("#,##0.##");

    for (int i = 0; i < jsonArray.length(); i++) {
        JSONObject product = jsonArray.getJSONObject(i);

        String product_description = product.optString("product_description", "");
        String productCode = product.optString("product_code", "");
        String product_uom = product.optString("product_uom", "");
        String product_hscode = product.optString("product_hscode", "");
        String product_standard_quantity = product.optString("product_standard_quantity", "");
        String product_other_notes = product.optString("product_other_notes", "");
        String rawMaterialTypeStr = product.optString("raw_material_type", "");

        try {
            double product_standard_quantity_num = Double.parseDouble(product_standard_quantity);
            product_standard_quantity = df.format(product_standard_quantity_num);
        } catch (Exception e) {
        }

        output.append("  <div class='card mb-3'>");
        output.append("    <div class='card-header product-header'>");
        output.append("      <strong>Product " + (i + 1) + ":</strong> " + product_description);
        if (!productCode.isEmpty()) {
            output.append(" (Code: " + productCode + ")");
        }
        output.append("    </div>");
        output.append("    <div class='card-body'>");

        output.append("      <table class='table table-sm table-bordered' style='margin-bottom: 15px;'>");
        output.append("        <tbody>");
        output.append("          <tr><td><strong>UOM:</strong></td><td>" + product_uom + "</td></tr>");
        output.append("          <tr><td><strong>HS Code:</strong></td><td>" + product_hscode + "</td></tr>");
        output.append("          <tr><td><strong>Standard Quantity:</strong></td><td>" + product_standard_quantity + "</td></tr>");
        if (!product_other_notes.isEmpty()) {
            output.append("          <tr><td><strong>Notes:</strong></td><td>" + product_other_notes + "</td></tr>");
        }
        output.append("        </tbody>");
        output.append("      </table>");

        if (!rawMaterialTypeStr.isEmpty()) {
            try {
                JSONArray rawMaterials = new JSONArray(rawMaterialTypeStr);

                output.append("      <h4 class='raw-material-header'>Raw Materials (" + rawMaterials.length() + " types):</h6>");
                output.append("      <table class='table table-sm table-bordered nested-table custom-table'>");
                output.append("        <thead class='thead-light'>");
                output.append("          <tr>");
                output.append("            <th>#</th>");
                output.append("            <th>Type Description</th>");
                output.append("            <th>UOM</th>");
                output.append("            <th>Quantity</th>");
                output.append("            <th>Waste Percentage %</th>");
                output.append("            <th>IOC</th>");
                output.append("            <th>Category</th>");
                output.append("            <th>HS Code</th>");
                output.append("          </tr>");
                output.append("        </thead>");
                output.append("        <tbody>");

                for (int j = 0; j < rawMaterials.length(); j++) {
                    JSONObject rawMaterial = rawMaterials.getJSONObject(j);

                    String typeDesc = rawMaterial.optString("raw_material_type_description", "");
                    String rmUom = rawMaterial.optString("uom", "");
                    String quantity = rawMaterial.optString("quantity", "");
                    String wastage = rawMaterial.optString("waste_percentage", "");
                    String ioc = rawMaterial.optString("input_output_coefficient", "");
                    String category = rawMaterial.optString("raw_material_type_code", "");
                    String rawMaterialInputStr = rawMaterial.optString("raw_material_input", "");

                    try {
                        double qtyNum = Double.parseDouble(quantity);
                        quantity = df.format(qtyNum);
                    } catch (Exception e) {
                    }

                    try {
                        double iocNum = Double.parseDouble(ioc);
                        ioc = df.format(iocNum);
                    } catch (Exception e) {
                    }

                    output.append("          <tr>");
                    output.append("            <td>" + (j + 1) + "</td>");
                    output.append("            <td>" + typeDesc + "</td>");
                    output.append("            <td>" + rmUom + "</td>");
                    output.append("            <td>" + quantity + "</td>");
                    output.append("            <td>" + wastage + "%</td>");
                    output.append("            <td>" + ioc + "</td>");
                    output.append("            <td>" + category + "</td>");
                    output.append("            <td>");
                    output.append("          </tr>");

                    if (!rawMaterialInputStr.isEmpty()) {
                        try {
                            JSONArray rawMaterialInputs = new JSONArray(rawMaterialInputStr);
							List rawMaterialInputsSortable = new ArrayList();
							for (int i = 0; i < rawMaterialInputs.length(); i++) {
								rawMaterialInputsSortable.add(rawMaterialInputs.getJSONObject(i));
							}

                            Collections.sort(rawMaterialInputsSortable, new Comparator() {
								public int compare(JSONObject a, JSONObject b) {
									String nameA = a.optString("input_code", "");
									String nameB = b.optString("input_code", "");
									return nameA.compareToIgnoreCase(nameB);
								}
							});
							JSONArray rawMaterialInputsSorted = new JSONArray();
							for (JSONObject obj : rawMaterialInputsSortable) {
								rawMaterialInputsSorted.put(obj);
							}

                            for (int k = 0; k < rawMaterialInputsSorted.length(); k++) {
                                JSONObject rmInput = rawMaterialInputsSorted.getJSONObject(k);

                                String rmInputDesc = rmInput.optString("input_description", "");
                                String rmInputUom = rmInput.optString("uom", "");
                                String rmInputHscode = rmInput.optString("hscode", "");
                                String rmInputCode = rmInput.optString("input_code", "");
                                String reqQty = rmInput.optString("quantity", "");
                                String waste = rmInput.optString("waste_percentage", "");
                                String inputCoeff = rmInput.optString("input_output_coefficient", "");
                                String ri_hscode = rmInput.optString("hscode", "");

                                try {
                                    double reqQtyNum = Double.parseDouble(reqQty);
                                    reqQty = df.format(reqQtyNum);
                                } catch (Exception e) {
                                }

                                try {
                                    double coeffNum = Double.parseDouble(inputCoeff);
                                    inputCoeff = df.format(coeffNum);
                                } catch (Exception e) {
                                }

                                output.append("          <tr class='raw-material-detail'>");
                                output.append("            <td></td>");
                                output.append("            <td style='padding-left: 20px;'>└ " + rmInputDesc + "</td>");
                                output.append("            <td>" + rmInputUom + "</td>");
                                output.append("            <td>" + reqQty + "</td>");
                                output.append("            <td>" + waste + "%</td>");
                                output.append("            <td>" + inputCoeff + "</td>");
                                output.append("            <td>" + rmInputCode + "</td>");
                                output.append("            <td>" + ri_hscode + "</td>");
                                output.append("</td>");
                                output.append("          </tr>");
                            }
                        } catch (Exception e) {
                        }
                    }
                }

                output.append("        </tbody>");
                output.append("      </table>");

            } catch (Exception e) {
                output.append("      <p class='text-warning'>Raw materials data format not recognized</p>");
            }
        }

        output.append("    </div>");
        output.append("  </div>");
    }

    output.append("</div>");

    if (jsonArray.length() == 0) {
        return "<em>No products found</em>";
    }

    return output.toString();

} catch (Exception e) {
    return "<span class='text-danger'>Error: Unable to parse product data - " + e.getMessage() + "</span>";
}
